};

const isWithin = (iso, startIso, endIso) => {
  if (!iso) {
    return false;
  }
  const at = DateTime.fromISO(iso).toMillis();
  return at >= DateTime.fromISO(startIso).toMillis() && at < DateTime.fromISO(endIso).toMillis();
};

const localTimeLabel = (iso, timezone) => DateTime.fromISO(iso).setZone(timezone).toFormat('HH:mm');

const hoursBefore = (iso, hours) => toUtcIso(DateTime.fromISO(iso).minus({ hours }));

