// Phone number helpers. South Africa (+27) is the default country.
// Twilio reports a withheld caller ID as "anonymous" or as +266696687 (ANONYMOUS on a keypad).
const WITHHELD_CALLER_IDS = [
  '',
  'anonymous',
  'restricted',
  'unknown',
  'private',
  'unavailable',
  'blocked',
  '+266696687',
  '266696687',
];

const E164_PATTERN = /^\+[1-9]\d{6,14}$/;

// Turns whatever the phone system sends into E.164, for example "+27000000012".
// Handles "082 ...", "27 82 ...", "0027 ...", "+27 (0)82 ..." and "sip:+27...@host".
const normalisePhone = (raw, defaultCountryCode = '27') => {
  const text = String(raw ?? '').trim().toLowerCase();
  if (WITHHELD_CALLER_IDS.includes(text)) {
    return { ok: false, issue: 'withheld' };
  }
  const withoutUri = text.replace(/^(sips?|tel):/, '').replace(/@.*$/, '');
  const withoutTrunkZero = withoutUri.replace(/\(0\)/g, '');
  const hasPlus = withoutTrunkZero.startsWith('+');
  const digits = withoutTrunkZero.replace(/\D/g, '');
  if (digits !== '' && WITHHELD_CALLER_IDS.includes(digits)) {
    return { ok: false, issue: 'withheld' };
  }
  const cc = defaultCountryCode;
  let e164 = '';
  if (hasPlus) {
    e164 = `+${digits}`;
  }
  else if (/^00[1-9]/.test(digits)) {
    e164 = `+${digits.slice(2)}`;
  }
  else if (digits.startsWith(cc) && digits.length === cc.length + 9) {
    e164 = `+${digits}`;
  }
  else if (digits.startsWith('0') && digits.length === 10) {
    e164 = `+${cc}${digits.slice(1)}`;
  }
  // "+27 0xx xxx xxxx" typed with the local trunk zero still in it.
  if (e164.startsWith(`+${cc}0`) && e164.length === cc.length + 11) {
    e164 = `+${cc}${e164.slice(cc.length + 2)}`;
  }
  return E164_PATTERN.test(e164) ? { ok: true, e164 } : { ok: false, issue: 'invalid' };
};

// Allowed prefixes come from Config as a comma separated list, for example "+27".
const parsePrefixList = (value) => String(value ?? '')
  .split(',')
  .map((part) => part.trim())
  .filter((part) => /^\+\d{1,4}$/.test(part));

const isAllowedCountry = (e164, allowedPrefixes) => allowedPrefixes.length === 0 || allowedPrefixes.some((prefix) => e164.startsWith(prefix));

// "+27000000012" becomes "+27 00 000 0012" for alerts a manager reads.
const formatPhoneForPeople = (e164) => {
  const match = /^\+27(\d{2})(\d{3})(\d{4})$/.exec(e164);
  return match ? `+27 ${match[1]} ${match[2]} ${match[3]}` : e164;
};

// ---- src/logic/reply.ts ----
// Classifies an inbound SMS reply and decides what the kit does with it.
// Opt out wins over everything else. STOP, UNSUBSCRIBE and OPT OUT count anywhere in the message.
// CANCEL, END, QUIT and friends only count as the whole message, so "cancel my order" or
// "remove olives" reaches the manager instead of silently opting someone out.
const OPT_OUT_ANYWHERE = ['STOP', 'STOPALL', 'UNSUBSCRIBE', 'OPTOUT'];

const OPT_OUT_PHRASES = ['OPT OUT', 'STOP ALL'];

const OPT_OUT_WHOLE_MESSAGE = ['CANCEL', 'END', 'QUIT', 'REVOKE', 'REMOVE ME'];

const BOOK_FIRST_WORDS = ['YES', 'Y', 'YEP', 'YEAH', 'JA'];

const BOOK_ANYWHERE = ['BOOK', 'BOOKING'];

const normaliseText = (body) => String(body ?? '')
  .toUpperCase()
  .replace(/[^A-Z0-9 ]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// Twilio adds OptOutType=STOP when its own opt out handling caught the message. Trust it too.
const classifyReply = (body, twilioOptOutType) => {
  if (String(twilioOptOutType ?? '').toUpperCase() === 'STOP') {
    return 'opt_out';
  }
  const text = normaliseText(body);
  if (text === '') {
    return 'other';
  }
  const words = text.split(' ');
  const padded = ` ${text} `;
  const optOut = words.some((word) => OPT_OUT_ANYWHERE.includes(word))
    || OPT_OUT_PHRASES.some((phrase) => padded.includes(` ${phrase} `))
    || OPT_OUT_WHOLE_MESSAGE.includes(text);
  if (optOut) {
    return 'opt_out';
  }
  if (BOOK_FIRST_WORDS.includes(words[0] ?? '') || words.some((word) => BOOK_ANYWHERE.includes(word))) {
    return 'book';
  }
  return 'other';
};

// A number that opted out never gets another SMS, even if it later asks for the link.
// The manager hears about it instead and can decide to phone them.
const decideReplyAction = (row, intent) => {
  if (row.is_new !== true) {
    return 'duplicate';
  }
  if (intent === 'opt_out') {
    return 'opted_out';
  }
  if (intent === 'book') {
    return row.opted_out_before === true ? 'blocked_opted_out' : 'link_sent';
  }
  return 'manager_alerted';
};

// Alerts carry at most this much of the customer's message.
const previewText = (body, maxLength = 300) => {
  const text = String(body ?? '').replace(/\s+/g, ' ').trim();
  return text.length > maxLength ? `${text.slice(0, maxLength - 3)}...` : text;
};

// ---- src/nodes/readReply.ts ----
// Code node "Read reply" in workflow 2. Input: the Config item, which carries Twilio's inbound SMS webhook.
const readReply = (item, realNowIso) => {
  const headers = readRecord(item.headers);
  const body = readRecord(item.body);
  const nowIso = resolveNow(realNowIso, configFlag(item, 'test_clock_enabled'), headers['x-hs-test-clock']);
  const messageSid = String(body.MessageSid ?? body.SmsSid ?? '').trim();
  const phone = normalisePhone(body.From);
  const valid = /^[A-Za-z0-9_-]{1,64}$/.test(messageSid) && phone.ok;
  return {
    valid,
    ignore_reason: valid ? null : 'missing MessageSid or a readable From number',
    message_sid: messageSid,
    from_e164: phone.ok ? phone.e164 : null,
    intent: classifyReply(body.Body, body.OptOutType),
    preview: previewText(body.Body),
    now_iso: nowIso,
  };
};

// ---- n8n entry point ----
return [{ json: readReply($input.first().json, $now.toISO()) }];

